\begin{aligned}
&\text{Kommutativ:} && a + b = b + a, \quad a \cdot b = b \cdot a \\
&\text{Assoziativ:} && (a + b) + c = a + (b + c), \quad (ab)c = a(bc) \\
&\text{Distributiv:} && a(b + c) = ab + ac
\end{aligned}

\begin{aligned}
[a, b] &= \{x \in \mathbb{R} \mid a \le x \le b\} && \text{abgeschlossen} \\
(a, b) &= \{x \in \mathbb{R} \mid a < x < b\} && \text{offen} \\
[a, b) &= \{x \in \mathbb{R} \mid a \le x < b\} && \text{halboffen} \\
[a, \infty) &= \{x \in \mathbb{R} \mid x \ge a\}
\end{aligned}
